let camera_2d_type = ComponentTypeId::new(engine::scene_bridge::CAMERA_2D_COMPONENT);
if let Some(Value::Object(fields)) = scene
    .entity(&info.id)
    .and_then(|entity| entity.components.get(&camera_2d_type))
{
    let height = (obj_f64_or(fields, "orthographic_height", 10.0)
        / obj_f64_or(fields, "zoom", 1.0).max(0.001)) as f32;
    let half_height = height * 0.5;
    let half_width = half_height * (16.0 / 9.0);
    let right = info.world.x_axis.truncate().normalize_or_zero();
    let up = info.world.y_axis.truncate().normalize_or_zero();
    let right = if right == Vec3::ZERO { Vec3::X } else { right };
    let up = if up == Vec3::ZERO { Vec3::Y } else { up };
    let color = Vec3::new(0.95, 0.45, 0.95);
    let corners = [
        info.center + right * half_width + up * half_height,
        info.center - right * half_width + up * half_height,
        info.center - right * half_width - up * half_height,
        info.center + right * half_width - up * half_height,
    ];
    for index in 0..4 {
        dl.line(corners[index], corners[(index + 1) % 4], color);
    }
    return;
}

